import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";

import { ActionLabelCollapseContext } from "../lib/header-actions";
import { cn } from "../lib/utils";
import { Icon, type IconSource } from "./icon";
import { Spinner } from "./spinner";
import { Tooltip, useReason } from "./tooltip";

import geometry from "./button-geometry.module.css";
import styles from "./button-material.module.css";
import controlStyles from "./controls.module.css";

const buttonVariants = cva(
  [
    geometry.button,
    controlStyles.focusOutline,
    "group/button inline-flex shrink-0 items-center justify-center border-transparent bg-clip-border whitespace-nowrap select-none disabled:pointer-events-none aria-invalid:border-[color:var(--cipher-control-invalid-border)] [&_svg]:pointer-events-none [&_svg]:shrink-0"
  ],
  {
    variants: {
      variant: {
        primary: styles.ink,
        accent: styles.material,
        "danger-ghost": "text-destructive hover:bg-destructive/10",
        default: styles.ink,
        outline: [
          "border-[color:var(--cipher-action-outline-border)] bg-[color:var(--cipher-action-outline-surface)] hover:bg-[color:var(--cipher-action-outline-hover)] hover:text-foreground [&[aria-haspopup]:is([data-state=open],[aria-expanded=true])]:bg-muted [&[aria-haspopup]:is([data-state=open],[aria-expanded=true])]:text-foreground",
          styles.neutralSelection
        ],
        secondary: [
          "bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] [&[aria-haspopup]:is([data-state=open],[aria-expanded=true])]:bg-secondary [&[aria-haspopup]:is([data-state=open],[aria-expanded=true])]:text-secondary-foreground",
          styles.neutralSelection
        ],
        ghost: [
          "hover:bg-[color:var(--cipher-action-ghost-hover)] hover:text-foreground [&[aria-haspopup]:is([data-state=open],[aria-expanded=true])]:bg-[color:var(--cipher-action-ghost-hover)] [&[aria-haspopup]:is([data-state=open],[aria-expanded=true])]:text-foreground",
          styles.neutralSelection
        ],
        bare: styles.bare,
        destructive: styles.danger,
        success: styles.success,
        link: styles.link
      },
      size: {
        md: geometry.regular,
        default: geometry.default,
        xs: geometry.extraSmall,
        sm: geometry.default,
        lg: geometry.large,
        icon: geometry.icon,
        "icon-xs": geometry.iconExtraSmall,
        "icon-sm": geometry.iconSmall,
        "icon-lg": geometry.iconLarge,
        "icon-row": geometry.iconRow
      }
    },
    compoundVariants: [
      {
        variant: [
          "primary",
          "default",
          "danger-ghost",
          "outline",
          "secondary",
          "ghost",
          "bare",
          "link"
        ],
        className: [styles.paintTransition, "disabled:opacity-50", styles.reasonDisabled]
      },
      { variant: ["destructive", "success"], className: styles.paintTransition }
    ],
    defaultVariants: {
      variant: "default",
      size: "default"
    }
  }
);

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  loading: loadingProp,
  loadingLabel,
  icon,
  iconRight,
  iconOnly: iconOnlyProp = false,
  selected,
  disabledReason,
  cornerBadge,
  layout,
  underline,
  applied = false,
  children,
  onClickCapture,
  onPointerDownCapture,
  onKeyDownCapture,
  onPointerDown,
  onPointerUp,
  onPointerLeave,
  onPointerCancel,
  style,
  type,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
    loading?: boolean;
    /** Text shown beside the spinner while loading, replacing the label, so the button's name says what is happening ("Saving"). Without it the label fades into a centered spinner. */
    loadingLabel?: string;
    icon?: IconSource;
    iconRight?: IconSource;
    iconOnly?: boolean;
    selected?: boolean;
    /** Disables the action and says why: it stays focusable, shows the reason in a tooltip and exposes it as the accessible description. */
    disabledReason?: string;
    /** A small Badge pinned to the top-right corner, straddling the border. It is part of the accessible name and never changes the button's size or hit area. */
    cornerBadge?: React.ReactNode;
    /** trigger: the label sits at the start and truncates and a chevron (iconRight, chev-down by default) sits at the end, with SelectTrigger's padding, for a Button that opens a menu, popover or picker. */
    layout?: "trigger";
    /** For variant link: always (the default) keeps the underline at rest; hover draws it only on hover and keyboard focus, for a record name in a table row. */
    underline?: "always" | "hover";
    /** A square dot on an icon-only trigger whose search or filter is in effect. Put any count in the label or tooltip, not in the button. */
    applied?: boolean;
  } & { ref?: React.Ref<React.ComponentRef<"button">> }) {
  const Comp = asChild ? Slot.Root : "button";
  const loading = loadingProp ?? false;
  const reason = disabledReason || undefined;
  const reasonTooltip = useReason(reason);
  const describedBy = reasonTooltip.describedBy(
    [
      props["aria-describedby"],
      asChild && React.isValidElement<{ "aria-describedby"?: string }>(children)
        ? children.props["aria-describedby"]
        : undefined
    ]
      .filter(Boolean)
      .join(" ") || undefined
  );
  const headerCollapsed = React.useContext(ActionLabelCollapseContext);
  const collapsible =
    headerCollapsed !== undefined &&
    Boolean(icon) &&
    !iconOnlyProp &&
    layout !== "trigger" &&
    !reason;
  const iconOnly = iconOnlyProp || (collapsible && headerCollapsed);
  const inactive =
    loading ||
    Boolean(reason) ||
    props.disabled ||
    props["aria-disabled"] === true ||
    props["aria-disabled"] === "true";
  const material = variant === "accent";
  const iconToggle =
    (selected ?? props["aria-pressed"]) !== undefined && (iconOnly || size?.startsWith("icon"));
  const resolvedVariant = variant === "ghost" && iconToggle ? "bare" : variant;
  const preventActivation = (event: React.SyntheticEvent) => {
    event.preventDefault();
    event.stopPropagation();
  };
  const popup = props["aria-haspopup"];
  const hasPopup = popup !== undefined && popup !== false && popup !== "false";
  const activationKey = (key: string) =>
    key === "Enter" || key === " " || (hasPopup && (key === "ArrowDown" || key === "ArrowUp"));
  const progress = (
    <Spinner
      data-slot="button-progress"
      className={styles.progress}
      data-active={loading || undefined}
    />
  );
  let iconSize: number | undefined = 14;
  if (size === "xs" || size === "icon-xs") iconSize = 12;
  else if (size === "md" || size === "lg") iconSize = 16;
  else if (size === "icon-row") iconSize = undefined;
  const iconDimension =
    iconSize === undefined
      ? undefined
      : iconOnly || size?.startsWith("icon")
        ? `var(--cipher-button-icon-size, ${iconSize}px)`
        : "var(--cipher-action-icon-size)";
  const trigger = layout === "trigger";
  const gateTooltip =
    <E extends React.SyntheticEvent>(handler?: (event: E) => void) =>
    (event: E) => {
      handler?.(event);
      if (!headerCollapsed) event.preventDefault();
    };
  const content = (label: React.ReactNode) => {
    const labelGroup = trigger ? (
      <>
        {icon && <Icon icon={icon} size={iconDimension} data-button-icon="" />}
        <span data-slot="button-label" className={geometry.triggerLabel}>
          {label}
        </span>
        <Icon
          icon={iconRight ?? "chev-down"}
          data-slot="button-chevron"
          className={geometry.triggerChevron}
        />
      </>
    ) : (
      <>
        {icon && <Icon icon={icon} size={iconDimension} data-button-icon="" />}
        {iconOnly && (icon || iconRight) ? (
          <span className="sr-only">{label}</span>
        ) : (
          label != null &&
          label !== false &&
          label !== "" && <span data-slot="button-text">{label}</span>
        )}
        {iconRight && <Icon icon={iconRight} size={iconDimension} />}
      </>
    );
    if (loadingProp === undefined) return labelGroup;
    if (loadingLabel !== undefined)
      return (
        <span data-slot="button-label-group" className={styles.labelGroup}>
          {loading ? (
            <>
              <Spinner />
              {loadingLabel}
            </>
          ) : (
            labelGroup
          )}
        </span>
      );
    return (
      <>
        <span data-slot="button-label-group" className={styles.labelGroup}>
          {labelGroup}
        </span>
        {progress}
      </>
    );
  };
  const badge = cornerBadge ? (
    <span data-slot="button-corner-badge" className={geometry.cornerBadge}>
      {cornerBadge}
    </span>
  ) : null;
  const marker = applied ? (
    <span aria-hidden data-slot="button-applied" className={geometry.appliedDot} />
  ) : null;
  const child =
    asChild &&
    React.isValidElement<{
      children?: React.ReactNode;
      onClickCapture?: React.MouseEventHandler<HTMLElement>;
      onPointerDownCapture?: React.PointerEventHandler<HTMLElement>;
      onKeyDownCapture?: React.KeyboardEventHandler<HTMLElement>;
    }>(children) ? (
      React.cloneElement(
        children,
        inactive
          ? {
              ...(reason && { "aria-describedby": describedBy }),
              onClickCapture: preventActivation,
              onPointerDownCapture: preventActivation,
              onKeyDownCapture: (event: React.KeyboardEvent<HTMLElement>) => {
                if (activationKey(event.key)) preventActivation(event);
                else children.props.onKeyDownCapture?.(event);
              }
            }
          : undefined,
        <>
          <span data-press="">{content(children.props.children)}</span>
          {badge}
          {marker}
          {reasonTooltip.description}
        </>
      )
    ) : (
      <>
        <span data-press="">{content(children)}</span>
        {badge}
        {marker}
        {reasonTooltip.description}
      </>
    );

  const button = (
    <Comp
      ref={ref}
      data-slot="button"
      data-variant={resolvedVariant}
      data-size={size}
      data-layout={layout}
      data-applied={applied || undefined}
      data-underline={variant === "link" ? (underline ?? "always") : undefined}
      type={asChild ? type : (type ?? "button")}
      {...props}
      disabled={reason ? undefined : props.disabled}
      data-cipher-button=""
      data-icon-only={iconOnly || undefined}
      data-cipher-button-material={material ? "" : undefined}
      data-disabled-reason={reason ? "" : undefined}
      aria-busy={loading || undefined}
      aria-disabled={
        loading || Boolean(reason) || props.disabled || props["aria-disabled"] || undefined
      }
      aria-describedby={describedBy}
      aria-pressed={selected ?? props["aria-pressed"]}
      onPointerMove={collapsible ? gateTooltip(props.onPointerMove) : props.onPointerMove}
      onFocus={collapsible ? gateTooltip(props.onFocus) : props.onFocus}
      className={cn(
        buttonVariants({ variant: resolvedVariant, size }),
        iconOnly && geometry.iconOnly,
        badge && geometry.badged,
        applied && geometry.applied,
        trigger && geometry.triggerLayout,
        loadingProp !== undefined && loadingLabel === undefined && styles.pendable,
        loading && loadingLabel === undefined && styles.pending,
        className
      )}
      style={style}
      onPointerDown={onPointerDown}
      onPointerUp={onPointerUp}
      onPointerLeave={onPointerLeave}
      onPointerCancel={onPointerCancel}
      onPointerDownCapture={(event) => {
        if (inactive) preventActivation(event);
        else onPointerDownCapture?.(event);
      }}
      onKeyDownCapture={(event) => {
        if (inactive && activationKey(event.key)) preventActivation(event);
        else onKeyDownCapture?.(event);
      }}
      onClickCapture={(event) => {
        if (inactive) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
    >
      {child}
    </Comp>
  );
  if (collapsible)
    return (
      // The tooltip stays mounted while the label shows, so collapsing never remounts the button;
      // an explicit delay keeps it off a surrounding TooltipScope, which would bypass the gate.
      <Tooltip
        delayDuration={200}
        content={
          asChild && React.isValidElement<{ children?: React.ReactNode }>(children)
            ? children.props.children
            : children
        }
      >
        {button}
      </Tooltip>
    );
  return reasonTooltip.wrap(button);
}
Button.displayName = "Button";

export { Button, buttonVariants };
